40	/**
41	 * KafkaPartitionLevelConnectionHandler provides low level APIs to access Kafka partition level information.
42	 * E.g. partition counts, offsets per partition.
43	 *
44	 */
45	public abstract class KafkaPartitionLevelConnectionHandler {
46	
47	  private static final Logger LOGGER = LoggerFactory.getLogger(KafkaPartitionLevelConnectionHandler.class);
48	  protected final KafkaPartitionLevelStreamConfig _config;
49	  protected final String _clientId;
50	  protected final int _partition;
51	  protected final String _topic;
52	  protected final Consumer<String, Bytes> _consumer;
53	  protected final TopicPartition _topicPartition;
54	  protected final KafkaMetadataExtractor _kafkaMetadataExtractor;
55	
56	  public KafkaPartitionLevelConnectionHandler(String clientId, StreamConfig streamConfig, int partition) {
57	    _config = new KafkaPartitionLevelStreamConfig(streamConfig);
58	    _clientId = clientId;
59	    _partition = partition;
60	    _topic = _config.getKafkaTopicName();
61	    Properties consumerProp = new Properties();
62	    consumerProp.putAll(streamConfig.getStreamConfigsMap());
63	    consumerProp.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, _config.getBootstrapHosts());
64	    consumerProp.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class.getName());
65	    consumerProp.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, BytesDeserializer.class.getName());
66	    if (_config.getKafkaIsolationLevel() != null) {
67	      consumerProp.put(ConsumerConfig.ISOLATION_LEVEL_CONFIG, _config.getKafkaIsolationLevel());
68	    }
69	    consumerProp.put(ConsumerConfig.CLIENT_ID_CONFIG, _clientId);
70	    _consumer = createConsumer(consumerProp);
71	    _topicPartition = new TopicPartition(_topic, _partition);
72	    _consumer.assign(Collections.singletonList(_topicPartition));
73	    _kafkaMetadataExtractor = KafkaMetadataExtractor.build(_config.isPopulateMetadata());
74	  }
75	
76	  private Consumer<String, Bytes> createConsumer(Properties consumerProp) {
77	    // Creation of the KafkaConsumer can fail for multiple reasons including DNS issues.
78	    // We arbitrarily chose 5 retries with 2 seconds sleep in between retries. 10 seconds total felt
79	    // like a good balance of not waiting too long for a retry, but also not retrying too many times.
80	    int maxTries = 5;
81	    int tries = 0;
82	    while (true) {
83	      try {
84	        return new KafkaConsumer<>(consumerProp);
85	      } catch (KafkaException e) {
86	        tries++;
87	        if (tries >= maxTries) {
88	          LOGGER.error("Caught exception while creating Kafka consumer, giving up", e);
89	          throw e;
90	        }
91	        LOGGER.warn("Caught exception while creating Kafka consumer, retrying {}/{}", tries, maxTries, e);
92	        // We are choosing to sleepUniterruptibly here because other parts of the Kafka consumer code do this
93	        // as well. We don't want random interrupts to cause us to fail to create the consumer and have the table
94	        // stuck in ERROR state.
95	        Uninterruptibles.sleepUninterruptibly(2, TimeUnit.SECONDS);
96	      }
97	    }
98	  }
99	
100	  public void close()
101	      throws IOException {
102	    _consumer.close();
103	  }
104	
105	  @VisibleForTesting
106	  protected KafkaPartitionLevelStreamConfig getKafkaPartitionLevelStreamConfig() {
107	    return _config;
108	  }
109	}
